import {hasSensitive} from './admin-permissions.mjs';
import {exceptionKinds,exceptionOutcomes,exceptionStatuses,exceptionIssues} from './exception-contract.mjs';
export function createExceptionViews({api,h,showPanel,localTime,writable,getUser,onReview}){
 const fmt=v=>v?localTime(v):'未登记';
 async function detail(id,offset=0){await showPanel('考勤异常核实',async signal=>{
  const [d,history]=await Promise.all([api.exceptionDetail(id,signal),api.exceptionHistory(id,offset,signal)]),p=d.period,admin=hasSensitive(getUser(),'personnel');
  return `<div class="dialog-header"><h2>${h(p.work_date)} · 考勤异常核实</h2><button class="icon-button" data-attendance-close aria-label="关闭异常核实详情">×</button></div><p>原始上班：${h(fmt(p.original_in))}；原始下班：${h(fmt(p.original_out))}</p><p>当前核准上班：${h(fmt(p.adjusted_in||p.original_in))}；当前核准下班：${h(fmt(p.adjusted_out||p.original_out))}</p>${d.eligible?`<p>实际时长：${Math.floor(d.metrics.durationMinutes/60)} 小时 ${d.metrics.durationMinutes%60} 分钟（午休不另扣）</p>`:`<p class="planning-rule">${h(exceptionIssues[d.issue]||'请先核对原打卡。')}</p>`}${d.rows.map(r=>`<article class="observation"><b>${h(exceptionKinds[r.kind])} · ${h(exceptionStatuses[r.reviewStatus])}</b><p>${!d.eligible?'时间资料待核对':r.flag?'当前时间规则仍命中该项，不因核实说明消除。':'当前核准时间未命中该项。'}</p>${r.latest?`<p>${h(r.latest.actor_name)} · ${h(fmt(r.latest.created_at))}</p><p class="preserve-text">${h(r.latest.note)}</p>${r.latest.period_version!==p.version?'<p class="muted">原考勤已变化，旧说明仅作历史追溯；当前仍有异常的需重新核实。</p>':''}`:'<p class="muted">暂无核实说明。</p>'}${writable&&admin&&d.eligible&&r.flag?`<div class="action-row"><button class="secondary" data-exception-review="${h(id)}" data-kind="${r.kind}">记录核实说明</button>${['confirmed','special'].includes(r.reviewStatus)?`<button class="text-button" data-exception-review="${h(id)}" data-kind="${r.kind}" data-reopen="true">重新待核实</button>`:''}</div>`:''}</article>`).join('')}<p class="muted">只按现有时间规则提示，工作日历、工资和扣款另行核实。</p><h3>核实历史</h3>${history.rows.map(r=>`<article class="observation"><b>${h(exceptionKinds[r.kind])} · ${h(exceptionOutcomes[r.outcome])}</b><p>${h(r.actor_name)} · ${h(fmt(r.created_at))}</p><p class="preserve-text">${h(r.note)}</p><p>核实时上班：${h(fmt(r.source_snapshot.adjusted_in||r.source_snapshot.original_in))}；下班：${h(fmt(r.source_snapshot.adjusted_out||r.source_snapshot.original_out))}</p></article>`).join('')||'<p class="muted">暂无核实历史。</p>'}<div class="pager"><button class="secondary" data-exception-detail="${h(id)}" data-history-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${history.total?offset+1+'–'+(offset+history.rows.length)+' / '+history.total:'0 条'}</span><button class="secondary" data-exception-detail="${h(id)}" data-history-offset="${offset+50}" ${offset+history.limit>=history.total?'disabled':''}>下一页</button></div>`;
 });}
 document.addEventListener('click',e=>{const d=e.target.closest('button[data-exception-detail]'),r=e.target.closest('button[data-exception-review]');if(d)detail(d.dataset.exceptionDetail,Number(d.dataset.historyOffset||0));if(r)onReview(r.dataset.exceptionReview,r.dataset.kind,r.dataset.reopen==='true');});
 return {row:r=>`<button class="asset-row" data-exception-detail="${h(r.periodId)}"><span><b>${h(r.memberName||'本人')}</b><small>${h(r.workDate)} · ${h(exceptionKinds[r.kind])}</small></span><span><b>${h(exceptionStatuses[r.reviewStatus])}</b><small>核准 ${h(fmt(r.effectiveIn))} — ${h(fmt(r.effectiveOut))} · ${Math.floor(r.durationMinutes/60)} 小时 ${r.durationMinutes%60} 分钟</small></span><span class="task-arrow">›</span></button>`};
}
